import{K as r,a as l,c as i,b as a,k as d,q as c,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 实战：制作可维护的项目报告","description":"将样式、自动目录、分节页码、图表题注、修订和 PDF 交付串成完整项目报告流程，附模板结构与验收清单。","frontmatter":{"title":"Word 实战：制作可维护的项目报告","description":"将样式、自动目录、分节页码、图表题注、修订和 PDF 交付串成完整项目报告流程，附模板结构与验收清单。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"实践案例","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"将样式、自动目录、分节页码、图表题注、修订和 PDF 交付串成完整项目报告流程，附模板结构与验收清单。","status":"active","related":[{"title":"Access 查询、窗体、报表与维护","link":"/tools/office/access/forms","kind":"使用指南","scope":"general","audience":"general"},{"title":"Access 入门、表设计与数据关系","link":"/tools/office/access/data","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas","kind":"使用指南","scope":"general","audience":"general"}],"prev":{"text":"Word 邮件合并、批量通知与标签","link":"/tools/office/word/mail-merge"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 邮件合并、批量通知与标签","link":"/tools/office/word/mail-merge"},"next":false},"headers":[],"relativePath":"tools/office/word/report.md","filePath":"tools/office/word/report.md"}'),h={name:"tools/office/word/report.md"},k=Object.assign(h,{setup(s){const t={path:"/tools/office/word/report",app:"Word",title:"交付一份可更新的项目报告",steps:[{tab:"开始",command:"样式",setting:"一级标题：背景 / 进展 / 风险 / 行动",anchor:"walkthrough-1"},{tab:"引用",command:"目录",setting:"自动目录；图表题注与交叉引用",anchor:"walkthrough-2"},{tab:"文件",command:"导出",setting:"定稿 PDF；同时保留可编辑源文件",anchor:"walkthrough-3"}]};return(f,e)=>{const o=r("OfficeGuide");return l(),i("div",null,[e[0]||(e[0]=a("h1",{id:"word-实战-制作可维护的项目报告",tabindex:"-1"},[d("Word 实战：制作可维护的项目报告 "),a("a",{class:"header-anchor",href:"#word-实战-制作可维护的项目报告","aria-label":'Permalink to "Word 实战：制作可维护的项目报告"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇把前面的操作组合成一份约六至十页的项目报告。页数仅用于练习，不要求为了凑页数扩写；交付质量取决于读者能否找到背景、证据、结论和行动。",-1)),c(o,{guide:t}),e[2]||(e[2]=n('<h2 id="outline" tabindex="-1">先写报告骨架 <a class="header-anchor" href="#outline" aria-label="Permalink to &quot;先写报告骨架 {#outline}&quot;">​</a></h2><p>按以下结构输入标题，先不要逐页装饰：封面、目录、摘要、项目背景、执行结果、问题与风险、下一步计划、附录。文档名用“标题”样式，正文大章用“标题 1”，子节用“标题 2”。</p><p>摘要回答四个问题：本期做了什么、结果如何、主要问题是什么、需要谁决定什么。结果部分注明统计区间和单位；不要只写“效果显著”，应提供可追溯的数据。行动计划至少包含事项、负责人和截止日期。</p><h2 id="format" tabindex="-1">建立可维护格式 <a class="header-anchor" href="#format" aria-label="Permalink to &quot;建立可维护格式 {#format}&quot;">​</a></h2><ol><li>保存工作文件，确定纸张、页边距和基本字体。</li><li>修改正文、标题 1、标题 2 样式，控制行距和段间距。</li><li>把多级编号关联到标题，确认导航窗格层级正确。</li><li>封面、目录和正文之间设置下一页分节符；按需要设置不同页码。</li><li>在目录页插入自动目录，在正文加入一张数据表和一张说明图。</li><li>为图表添加题注，在正文中通过交叉引用引用编号。</li></ol><p>不要给每一页独立设置字体和手动补空行。以后只要修改样式或增加内容，文档应能够自动重新排版。</p><h2 id="evidence" tabindex="-1">表格、图片和证据 <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;表格、图片和证据 {#evidence}&quot;">​</a></h2><p>结果表可以使用“指标、目标、实际、差异、说明”五列。涉及比例时写清分子分母，差异注明是金额差、百分比变化还是百分点变化。图表旁边记录数据文件名、工作表、统计日期和筛选条件，使审核人能回到原数据。</p><p>正文写“见表 1”后说明表中最重要的发现，不能让读者自行寻找结论。宽表先减少不必要列，再考虑横向分节页。长表启用重复表头，检查是否存在因禁止跨页断行导致的大面积留白。</p><h2 id="review" tabindex="-1">审阅与定稿流程 <a class="header-anchor" href="#review" aria-label="Permalink to &quot;审阅与定稿流程 {#review}&quot;">​</a></h2><p>把工作稿交给审阅人前，约定使用修订和批注，并指定最终合并责任人。收到反馈后逐条处理，重要结论需要回到数据核对；不能为了让红色标记消失就接受所有修改。</p><p>定稿副本中处理修订与批注，更新目录、题注和交叉引用。检查页眉页脚、文档属性、嵌入对象和外部链接，再导出 PDF。源文件与 PDF 使用相同版本标识，例如 <code>项目报告_2026-11_v1.0.docx</code> 和同名 PDF。</p><h2 id="acceptance" tabindex="-1">验收清单 <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;验收清单 {#acceptance}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>合格表现</th></tr></thead><tbody><tr><td>文档结构</td><td>导航窗格与目录均能定位各章，层级无跳跃</td></tr><tr><td>自动维护</td><td>插入新章后编号和目录可正确更新</td></tr><tr><td>页面</td><td>封面、目录、正文的页码符合约定，无意外空白页</td></tr><tr><td>图表</td><td>字体可读、单位明确、编号和引用一致</td></tr><tr><td>内容</td><td>数据有口径和来源，结论与证据相符</td></tr><tr><td>审阅</td><td>未决问题被明确标出，定稿无意外隐藏修订</td></tr><tr><td>输出</td><td>PDF 页数、字体和表格与预期一致</td></tr></tbody></table><h2 id="practice" tabindex="-1">练习与参考结果 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与参考结果 {#practice}&quot;">​</a></h2><p>先完成报告，再故意做三次变更：在第二章前加一章、把结果表扩展到下一页、删除第一张图。完成字段更新和排版检查后，编号应连续，目录应与实际一致，长表第二页应有表头，正文中不能留有失效交叉引用。</p><p>最后将报告另存为模板副本，移除真实数据和旧批注，保留结构、样式和填写说明。下一次新建报告时，应能直接使用模板，而无需复制上一份已定稿报告再逐处删除旧内容。</p><p>需要回看操作时，按<a href="/tools/office/word/styles">样式</a>、<a href="/tools/office/word/sections">分节</a>、<a href="/tools/office/word/images-references">图文引用</a>、<a href="/tools/office/word/review">审阅</a>顺序定位。</p><h2 id="walkthrough" tabindex="-1">图示跟做：交付一份可更新的项目报告 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：交付一份可更新的项目报告 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先形成可导航骨架 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先形成可导航骨架 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：开始 → 样式。</strong></p><p>输入报告标题和四个章节，用标题 1 标记章节，再给进展中的里程碑使用标题 2。打开导航窗格检查阅读顺序。每章先写一句明确结论：已经完成什么、目前缺什么、谁在什么时间做什么，再补证据，避免先用大量装饰挤占正文空间。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：把结构和证据连起来 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：把结构和证据连起来 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：引用 → 目录。</strong></p><p>在开头插入自动目录；表格记录负责人和期限，插图添加题注，正文用交叉引用说明证据位置。统计数字注明来源文件、日期范围和单位。重新排版后更新目录与相关域，确认目录页码和图号能指向真正的内容。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：按交付清单逐项检查 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：按交付清单逐项检查 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 导出。</strong></p><p>先处理修订和批注，再导出 PDF。逐页核对页码、表格边缘、长链接、横向页和末页，随机选两个数字回查 Excel。最终交付包放报告源文件、PDF、数据口径说明；不要把含临时意见的版本仅改名为“最终版”就外发。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>报告标题、目录和正文结论不一致时，优先修正结构。示例中的月度金额只有在完成同一范围的 Excel 核对后才能复用，别把演示数字带进真实经营材料。</p>',31))])}}});export{u as __pageData,k as default};
